struct SoftCap {
  static constexpr bool use_softmax = true;
  float cap;
  SoftCap(const Params& params, int batch_idx, uint8_t* smem_ptr) {
    cap = params.cap;
  }
  float LogitsTransform(const Params& params, float logits,
                        int batch_idx, int qo_idx, int kv_idx,
                        int qo_head_idx, int kv_head_idx) {
    return cap * tanhf(logits / cap);
  }
};
